export const CODE_REVIEW_TEMPLATE = "# Copy to .github/workflows/code-review.yml in each repository to review.\n# Needs one secret: ANTHROPIC_API_KEY (repo or organization secret).\n# Replace <commit-sha> with the full commit hash of the release you want, and keep the version in\n# the trailing comment (see README, \"Add it to a repository\"). Pin by hash, never by tag.\n#\n# A review runs when a PR is opened, reopened or marked ready for review.\n# To ask for another review, add the `re-review` label to the PR. The reviewer\n# removes the label when it finishes, so it can be added again. Create the\n# label once per repository (any colour). Labels are used instead of comment\n# triggers because an issue_comment trigger starts a (skipped) Actions run on\n# every comment on every PR.\n#\n# Optional merge blocking: set \"blockOn\" in .simpli-review/config.json and make the\n# job (named \"review\" below) a required status check. A PR with the\n# `review-override` label (config \"overrideLabel\") is let through. The label is read\n# from the PR the reviewer fetches, so the permissions below are enough. Adding that\n# label does not start a review; add `re-review` afterwards to refresh the check.\nname: Code review\n\non:\n  pull_request:\n    # Add `synchronize` here AND \"push\" to autoReview in .simpli-review/config.json\n    # to review every push; otherwise a push would only cancel a running review.\n    types: [opened, reopened, ready_for_review, labeled]\n    # Docs-only PRs are not reviewed (this also means a re-review label on a\n    # docs-only PR does nothing).\n    paths-ignore:\n      - \"**/*.md\"\n      - \"docs/**\"\n\npermissions:\n  contents: read\n  pull-requests: write\n  issues: write\n\njobs:\n  review:\n    # Skip drafts, and skip `labeled` events for any label other than\n    # `re-review`. If you set \"reReviewLabel\" in .simpli-review/config.json,\n    # use the same name here.\n    if: >-\n      github.event.pull_request.draft == false &&\n      (github.event.action != 'labeled' || github.event.label.name == 're-review')\n    # Job-level, so a skipped run never joins the group and cancels anything.\n    concurrency:\n      group: code-review-${{ github.event.pull_request.number }}\n      cancel-in-progress: true\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    steps:\n      # The reviewer reads the code at the PR's head commit.\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1\n        with:\n          ref: ${{ github.event.pull_request.head.sha }}\n          fetch-depth: 50          # some history for the git_history tool\n          persist-credentials: false\n      - uses: simpli-software/simpli-review@<commit-sha> # v1.x\n        with:\n          name: Code Review       # summary heading\n          anthropic-api-key: ${{ secrets.ANTHROPIC_API_KEY }}\n";
export const AI_SCAN_TEMPLATE = "# Monthly full-repository AI security scan (first Monday of the month). Copy to .github/workflows/ai-scan.yml\n# in each repository, or run `simpli-review init`, which writes this file with the pin filled in.\n# Needs one secret: ANTHROPIC_API_KEY (repo or organization secret).\n#\n# What it does: reads the whole repository at the latest commit of the default branch, opens at most\n# `scan.maxIssues` issues labelled `ai-scan` (created if missing) for the worst findings, and writes a\n# spend report (tokens and an estimated cost in USD) to the job summary and to the `simpli-review-scan`\n# artifact. See README.md, \"AI scan\". Cost is capped by `scan.maxInputTokens` and `scan.maxTurns` in\n# .simpli-review/config.json; run it by hand first (Actions > AI scan > Run workflow) to see the real spend.\n#\n# Pin the actions by commit hash. The simpli-review line below carries a placeholder: replace\n# <commit-sha> with the commit hash of a release that has scan mode (look the hash up with\n#   gh api repos/simpli-software/simpli-review/git/ref/tags/<tag> --jq '.object.sha'\n# and if that returns an annotated tag, resolve it with\n#   gh api repos/simpli-software/simpli-review/git/tags/<sha> --jq '.object.sha' )\n# and keep the version in the trailing comment. Dependabot can update hash-pinned actions.\nname: AI scan\n\non:\n  schedule:\n    # Every Monday 09:17 UTC; the `when` job lets only the first Monday of the month through.\n    # Cron cannot say \"first Monday\": \"1-7 * 1\" means day 1-7 OR Monday.\n    - cron: \"17 9 * * 1\"\n  workflow_dispatch:\n    inputs:\n      effort:\n        description: \"Reasoning effort: low, medium, high, xhigh or max. Empty uses scan.effort from the config (default high).\"\n        required: false\n        default: \"\"\n        type: string\n      max-turns:\n        description: \"Upper bound on investigation turns. Empty uses scan.maxTurns from the config (default 60).\"\n        required: false\n        default: \"\"\n        type: string\n\npermissions: {}\n\n# Two scans never overlap: a manual run waits for the scheduled one instead of cancelling it.\nconcurrency:\n  group: ai-scan\n  cancel-in-progress: false\n\njobs:\n  when:\n    runs-on: ubuntu-latest\n    timeout-minutes: 2\n    outputs:\n      run: ${{ steps.day.outputs.run }}\n    steps:\n      - name: First Monday of the month, or a manual run\n        id: day\n        env:\n          EVENT: ${{ github.event_name }}\n        run: |\n          if [ \"$EVENT\" != \"schedule\" ] || [ \"$(date -u +%-d)\" -le 7 ]; then\n            echo \"run=true\" >> \"$GITHUB_OUTPUT\"\n          else\n            echo \"run=false\" >> \"$GITHUB_OUTPUT\"\n          fi\n\n  scan:\n    needs: when\n    if: needs.when.outputs.run == 'true'\n    permissions:\n      contents: read\n      issues: write\n    runs-on: ubuntu-latest\n    timeout-minutes: 45\n    steps:\n      - name: Check out the default branch\n        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1\n        with:\n          fetch-depth: 200 # history for the git_history tool\n          persist-credentials: false\n      - name: Scan\n        uses: simpli-software/simpli-review@<commit-sha> # v1.x\n        with:\n          mode: scan\n          name: AI scan # heading of the report\n          anthropic-api-key: ${{ secrets.ANTHROPIC_API_KEY }}\n          effort: ${{ inputs.effort }}\n          max-turns: ${{ inputs.max-turns }}\n      - name: Upload the scan report\n        if: ${{ !cancelled() }} # a failed scan still spent money: keep its report\n        uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2\n        with:\n          name: simpli-review-scan\n          path: |\n            simpli-review-scan.json\n            simpli-review-scan.md\n          if-no-files-found: warn\n          retention-days: 90\n";
export const SECURITY_SCAN_TEMPLATE = "# Copy to .github/workflows/security-scan.yml in each application repository.\n# Optional secret: ANTHROPIC_API_KEY (enables Claude triage; scanning works without it).\n# Optional config: .simpli-guard/config.json (see examples/config/example.json).\n#\n# Replace <commit-sha> with the full 40-character commit hash of the release you want, keeping the\n# tag in the comment.\n# The placeholder is deliberate: the Actions scan (zizmor) flags a tag or branch reference as\n# unpinned, and a commit hash cannot be moved after the fact.\nname: Security scan\n\non:\n  pull_request:\n    types: [opened, synchronize, reopened, ready_for_review]\n  schedule:\n    - cron: \"17 3 * * *\" # nightly, 03:17 UTC\n  workflow_dispatch:\n\npermissions: {} # each job asks for exactly what it needs\n\njobs:\n  pr:\n    if: github.event_name == 'pull_request'\n    # Job-level, so a newer push cancels the older scan of the same PR only.\n    concurrency:\n      group: security-scan-pr-${{ github.event.pull_request.number }}\n      cancel-in-progress: true\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    permissions:\n      contents: read\n      pull-requests: write # the one summary comment\n    steps:\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1\n        with:\n          fetch-depth: 0 # the base commit is checked out into a worktree and scanned too\n          persist-credentials: false\n      - uses: simpli-software/simpli-guard@<commit-sha> # v1.x\n        with:\n          mode: pr\n          anthropic-api-key: ${{ secrets.ANTHROPIC_API_KEY }}\n\n  nightly:\n    if: github.event_name == 'schedule' || github.event_name == 'workflow_dispatch'\n    concurrency:\n      group: security-scan-nightly-${{ github.ref }}\n      cancel-in-progress: false\n    runs-on: ubuntu-latest\n    timeout-minutes: 60\n    permissions:\n      contents: read\n      issues: write # open/close one issue per critical/high finding\n    steps:\n      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1\n        with:\n          fetch-depth: 0 # full history for the secrets scan\n          persist-credentials: false\n      - uses: simpli-software/simpli-guard@<commit-sha> # v1.x\n        with:\n          mode: nightly\n          anthropic-api-key: ${{ secrets.ANTHROPIC_API_KEY }}\n";
